 auto terrain=category(0,0);std::array<size_t,4>visible{};for(unsigned kind=0;kind<3;++kind){size_t first=kind==0?0:kind==1?world.shpCount:world.shpCount+world.vxlCount,end=kind==0?world.shpCount:kind==1?world.shpCount+world.vxlCount:world.draws.size();auto out=category(first,end);for(size_t n=0;n<out.size();++n)visible[kind]+=out[n]!=terrain[n];assert(visible[kind]>0);}
