 std::ostringstream report;report<<std::setprecision(9)<<"{\"path\":\"CPU ObjectCanvas -> NativeCanvas::present -> WorldEffects::Painter\",\"tier\":\""<<(high?"high":"medium")<<"\",\"synthetic_encoded_assets\":true,\"real_game_fps\":false,\"seed\":"<<world.seed<<",\"incremental_resolve\":"<<(dirty?"true":"false")<<",\"frames\":"<<frames<<",\"warmup_frames\":"<<warmup<<",\"output\":["<<w<<","<<h<<"],\"native_world\":["<<world.width<<","<<world.height<<"],\"counts\":{\"terrain\":"<<world.tileCount<<",\"shp_actors\":"<<world.shpCount<<",\"vxl_actors\":"<<world.vxlCount<<",\"animated_shp\":"<<world.animationCount<<",\"particle_points\":"<<world.particleCount<<",\"beams\":"<<world.beamCount<<",\"vxl_model_exposed_faces\":"<<world.modelFaces<<",\"vxl_unique_poses\":"<<world.voxels.size()<<",\"prepared_triangle_total\":"<<world.preparedTriangles<<",\"decoded_tmp_frames\":"<<world.decodedTmpFrames<<",\"decoded_shp_rle_frames\":"<<world.decodedShpFrames<<",\"decoded_vxl_hva_parts\":"<<world.decodedVxlParts<<"},\"initialization_ms\":"<<initMs<<",\"cold_first_frame_ms\":"<<coldFrame<<",\"cold_voxel_rasters\":"<<coldRasters<<",\"completed_changed_frames\":"<<changedFrames<<",\"final_pixel_hash\":\""<<finalHash<<"\",\"visible_content_checks\":{\"shp_pixels_different_from_terrain\":"<<visible[0]<<",\"vxl_pixels_different_from_terrain\":"<<visible[1]<<",\"animation_pixels_different_from_terrain\":"<<visible[2]<<",\"effect_pixels_different_from_full_world\":"<<visible[3]<<"},\"verification_hash_and_preview_excluded_from_timings\":true,\"stages\":{";
 bool first=true,countMode=false;auto stage=[&](const char*name,const Samples&s){if(!first)report<<",";first=false;report<<"\""<<name<<"\":";s.json(report,!countMode);};stage("state_update",update);stage("native_composition",compose);stage("whole_map_resolve",resolve);stage("particles_and_beams",effects);stage("frame_compute",complete);report<<"},\"terrain_light_phase_interval_frames\":60,\"terrain_light_updates_including_setup\":"<<world.terrainLightUpdates<<",\"work_per_frame\":{";first=true;countMode=true;stage("changed_native_pages",changed);stage("reused_native_pages",reused);stage("new_voxel_raster_jobs",rasterBuilds);report<<"}}\n";
 if(!hashes.empty()){std::ofstream file(hashes);file<<"[";for(size_t n=0;n<frameHashes.size();++n)file<<(n?",":"")<<"\""<<frameHashes[n]<<"\"";file<<"]\n";if(!file)throw std::runtime_error("hash report write failed");}
